122	// Creates a shallow clone of this CopyNode.
123	TileOperator CopyNode::Clone() const {
124	  auto op = tvm::ffi::make_object<CopyNode>(*this);
125	  if (par_op_.defined()) {
126	    op->par_op_ = Downcast<ParallelOp>(par_op_->Clone());
127	  }
128	  return Copy(op);
129	}
