226	// Generates index expressions for accessing src (src_dst=0) or dst (src_dst=1)
227	// buffers.
228	Array<PrimExpr> CopyNode::MakeIndices(const Array<IterVar> &ivs,
229	                                      int src_dst) const {
230	  Array<PrimExpr> indices;
231	  Array<Range> ranges = src_dst == 0 ? src_range : dst_range;
232	  size_t idx = 0;
233	  for (size_t i = 0; i < ranges.size(); i++) {
234	    if (is_one(ranges[i]->extent))
235	      indices.push_back(ranges[i]->min);
236	    else {
237	      indices.push_back(ranges[i]->min + ivs[idx]->var);
238	      idx++;
239	    }
240	  }
241	  ICHECK(idx == ivs.size())
242	      << "idx = " << idx << ", ivs.size() = " << ivs.size()
243	      << "src name = " << src->name << ", dst name = " << dst->name;
244	  return indices;
245	}
