280	// Constructs a SIMT-style nested loop that implements the copy.
281	For CopyNode::MakeSIMTLoop(arith::Analyzer *analyzer) const {
282	  Array<IterVar> loop_vars = MakeIterVars();
283	  bool is_scalar = loop_vars.empty();
284	
285	  for (const auto &iv : loop_vars)
286	    analyzer->Bind(iv->var, iv->dom);
287	  ICHECK(loop_vars.size() <= src_range.size())
288	      << "loop_vars.size() = " << loop_vars.size()
289	      << ", src_range.size() = " << src_range.size() << ", src = " << src->name
290	      << ", dst = " << dst->name;
291	
292	  ICHECK(loop_vars.size() <= dst_range.size())
293	      << "loop_vars.size() = " << loop_vars.size()
294	      << ", dst_range.size() = " << dst_range.size() << ", src = " << src->name
295	      << ", dst = " << dst->name;
296	
297	  Array<PrimExpr> src_indices = MakeIndices(loop_vars, 0);
298	  Array<PrimExpr> dst_indices = MakeIndices(loop_vars, 1);
299	
300	  PrimExpr src_predicate = MakePredicate(analyzer, loop_vars, src->shape, 0);
301	  PrimExpr dst_predicate = MakePredicate(analyzer, loop_vars, dst->shape, 1);
302	
303	  PrimExpr value = BufferLoad(src, src_indices);
304	  if (src->dtype != dst->dtype)
305	    value = Cast(dst->dtype, value);
306	  if (src_predicate.defined())
307	    value = if_then_else(src_predicate, value, make_zero(dst->dtype));
308	
309	  Stmt body = BufferStore(dst, value, dst_indices);
310	  if (dst_predicate.defined())
311	    body = IfThenElse(dst_predicate, body);
312	  if (is_scalar) {
313	    return For(Var("i"), 0, 1, ForKind::kSerial, body);
314	  }
315	  for (int i = loop_vars.size() - 1; i >= 0; i--) {
316	    Map<String, ObjectRef> loop_annotations;
317	    if (annotations.count(attr::kCoalescedWidth)) {
318	      loop_annotations.Set(attr::kCoalescedWidth,
319	                           annotations.Get(attr::kCoalescedWidth).value());
320	    }
321	    body = For(loop_vars[i]->var, 0, loop_vars[i]->dom->extent,
322	               ForKind::kParallel, body, std::nullopt, loop_annotations);
323	  }
324	  return Downcast<For>(body);
325	}
