327	// Computes a linearized shared-memory layout for TMA transfers.
328	// Maps [i, j] -> [i // 256, j // 256, i % 256, j % 256]
329	Layout CopyNode::ComputeLinearLayout(const Buffer &shared_tensor) const {
330	  Array<PrimExpr> input_size = shared_tensor->shape;
331	  Array<PrimExpr> forward_vars;
332	  for (size_t i = 0; i < input_size.size(); i++) {
333	    forward_vars.push_back(InputPlaceholder(i));
334	  }
335	  // [i, j] -> [i // 256, j // 256, i % 256, j % 256]
336	  Array<PrimExpr> forward_index;
337	  for (size_t i = 0; i < input_size.size(); i++) {
338	    forward_index.push_back(FloorDiv(forward_vars[i], 256));
339	  }
340	  for (size_t i = 0; i < input_size.size(); i++) {
341	    forward_index.push_back(FloorMod(forward_vars[i], 256));
342	  }
343	  return Layout(input_size, forward_index);
344	}
