346	// Infers memory layouts for this Copy operation based on target and copy
347	// instruction.
348	LayoutMap CopyNode::InferLayout(const LayoutInferArgs &T,
349	                                InferLevel level) const {
350	  auto target = T.target;
351	  using namespace tvm::transform;
352	  PassContext pass_ctx = PassContext::Current();
353	  bool disable_tma_lower =
354	      pass_ctx->GetConfig<Bool>(kDisableTMALower, Bool(false)).value();
355	  auto copy_inst = GetCopyInst(target, disable_tma_lower || GetDisableTMA(),
356	                               T.layout_map, T.analyzer, T.buffer_oob);
357	
358	  // Handle tensor memory (tmem) layout inference
359	  if (copy_inst == CopyInst::kTMemLoad || copy_inst == CopyInst::kTMemStore) {
360	    // Tensor memory copy
361	    // TODO (mzw) Add support for tcgen05.st/cp (in conj. with LowerTmemCopy)
362	    ICHECK(copy_inst == CopyInst::kTMemLoad)
363	        << "Only support tensor memory copy from shared.tmem to local.fragment "
364	           "currently";
365	    LayoutMap results;
366	    if (!T.layout_map.count(dst) && T.layout_map.count(src)) {
367	      // Use the default layout (32dp32b) if not specified
368	      // NOTE (mzw) We will check the layout in LowerTmemCopy(), so don't
369	      // worry for tmem-incompatible layout
370	      Layout src_layout = T.layout_map[src];
371	      Array<IterVar> logical_coords = MakeIterVars();
372	      Array<PrimExpr> logical_coords_var = {logical_coords[0]->var,
373	                                            logical_coords[1]->var};
374	      Array<PrimExpr> phy_indices = src_layout->Forward(logical_coords_var);
375	
376	      // Tmem physical coord range analysis
377	      auto analyzer = std::make_shared<arith::Analyzer>();
378	      for (const auto &iv : logical_coords)
379	        analyzer->Bind(iv->var, iv->dom);
380	      arith::ConstIntBound phy_row_bounds =
381	          analyzer->const_int_bound(phy_indices[0]);
382	      arith::ConstIntBound phy_col_bounds =
383	          analyzer->const_int_bound(phy_indices[1]);
384	      Range row_dom = Range((int)(phy_row_bounds->min_value),
385	                            (int)(phy_row_bounds->max_value + 1));
386	      Range col_dom = Range((int)(phy_col_bounds->min_value),
387	                            (int)(phy_col_bounds->max_value + 1));
388	
389	      constexpr int WARP_SIZE = 32; // Set to 32 since only sm100 is supported
390	      constexpr int WARPGROUP_SIZE = 4 * WARP_SIZE;
391	      ICHECK(is_const_int(T.thread_bounds->extent))
392	          << "Tensor memory copy requires thread_bounds->extent (num_threads) "
393	             "to be constant integers";
394	      int num_threads = *as_const_int(T.thread_bounds->extent);
395	      ICHECK(num_threads % WARPGROUP_SIZE == 0)
396	          << "Tensor memory copy requires thread bounds to be aligned to "
397	             "warpgroups, but found "
398	          << "thread range = " << T.thread_bounds;
399	
400	      for (int num_useful_wgs = num_threads / WARPGROUP_SIZE;
401	           num_useful_wgs >= 1; --num_useful_wgs) {
402	        int num_useful_threads = num_useful_wgs * WARPGROUP_SIZE;
403	        Tcgen05Meta meta = getTcgen05Meta_32dp32b();
404	        auto [is_success, tmem_coord2frag, num_chunks_each_wg] =
405	            expandTcgen05Layout(
406	                meta, phy_col_bounds->max_value - phy_col_bounds->min_value + 1,
407	                num_useful_threads, row_dom, col_dom);
408	        if (!is_success) {
409	          continue;
410	        }
411	        Fragment logical_coord2frag =
412	            Fragment(logical_coords, tmem_coord2frag->Forward(phy_indices),
413	                     tmem_coord2frag->ForwardThread(phy_indices, std::nullopt),
414	                     make_itervar("rep", 1));
415	        results.Set(dst, logical_coord2frag->BindThreadRange(T.thread_bounds));
416	        break;
417	      }
418	    }
419	    return results;
420	  }
421	
422	  if (copy_inst == CopyInst::kBulkLoad || copy_inst == CopyInst::kBulkStore ||
423	      copy_inst == CopyInst::kBulkLoad1D ||
424	      copy_inst == CopyInst::kBulkStore1D) {
425	    // if can apply swizzling, we skip layout inference
426	    // for bulk load/store, we can directly apply the layout of normal copy
427	    // This must be a global/shared layout, so we can skip the parallel op
428	    // layout inference (parallel layout inference only annotate the loop layout
429	    // and the register layout).
430	    Map<Buffer, Layout> result_map;
431	
432	    bool is_tma_1d = copy_inst == CopyInst::kBulkLoad1D ||
433	                     copy_inst == CopyInst::kBulkStore1D;
434	    bool is_load =
435	        copy_inst == CopyInst::kBulkLoad || copy_inst == CopyInst::kBulkLoad1D;
436	    bool is_store = copy_inst == CopyInst::kBulkStore ||
437	                    copy_inst == CopyInst::kBulkStore1D;
438	    auto global_tensor = is_load ? src : dst;
439	    auto shared_tensor = is_load ? dst : src;
440	    auto shared_range = is_load ? dst_range : src_range;
441	
442	    if (is_tma_1d && shared_range.size() == 1) {
443	      // 1D TMA Store with single dimension can not be swizzled
444	      // But 1D TMA can also have multiple dimensions when the last
445	      // dimension is continuous.
446	      return result_map;
447	    }
448	
449	    // Collect fragment buffers from indices and mark them as fully replicated
450	    // For Bulk Load/Store, fragment buffers used as indices should be
451	    // replicated across all threads
452	    PrimExpr thread_extent = T.thread_bounds->extent;
453	    for (const auto &range : src_range) {
454	      CollectFragmentLayouts(range->min, T.let_var_to_expr, T.layout_map,
455	                             thread_extent, T.thread_bounds, result_map);
456	      CollectFragmentLayouts(range->extent, T.let_var_to_expr, T.layout_map,
457	                             thread_extent, T.thread_bounds, result_map);
458	    }
459	    for (const auto &range : dst_range) {
460	      CollectFragmentLayouts(range->min, T.let_var_to_expr, T.layout_map,
461	                             thread_extent, T.thread_bounds, result_map);
462	      CollectFragmentLayouts(range->extent, T.let_var_to_expr, T.layout_map,
463	                             thread_extent, T.thread_bounds, result_map);
464	    }
465	
466	    // check shared layout is non-swizzle
467	    // skip layout inference if shared layout is already annotated
468	    if (level == InferLevel::kFree && !T.layout_map.count(shared_tensor)) {
469	      if (is_store) {
470	        // For BulkStore, we should perform swizzle if possible.
471	        // TMA Store is always 1d like, we can directly use the last two
472	        // dimensions to analysis swizzling.
473	        int dim = shared_tensor->shape.size();
474	        const int64_t mat_stride = *as_const_int(shared_tensor->shape[dim - 2]);
475	        const int64_t mat_continuous =
476	            *as_const_int(shared_tensor->shape[dim - 1]);
477	        Layout swizzle_layout = makeGemmABLayoutHopper(
478	            mat_stride, mat_continuous, mat_continuous,
479	            shared_tensor->dtype.bits(), /*k_inner=*/true);
480	        // If makeGemmABLayoutHopper returns a linear layout, fallback to
481	        // ComputeLinearLayout which handles arbitrary tensor shapes correctly.
482	        if (StructuralEqual()(swizzle_layout, makeLinearLayout(Array<PrimExpr>{
483	                                                  Integer(mat_stride),
484	                                                  Integer(mat_continuous)}))) {
485	          result_map.Set(shared_tensor, ComputeLinearLayout(shared_tensor));
486	        } else {
487	          result_map.Set(shared_tensor, swizzle_layout);
488	        }
489	      } else if (level == InferLevel::kFree) {
490	        // create a new layout map for tma linear layout
491	        Layout linear_layout = ComputeLinearLayout(shared_tensor);
492	        result_map.Set(shared_tensor, linear_layout);
493	      }
494	    }
495	    return result_map;
496	  }
497	
498	  // for LDSM/STSM, the layout was deduced from register layout
499	  // so we can directly apply the layout of normal copy
500	  // Use parallel op to infer the layout
501	  if (!par_op_.defined()) {
502	    arith::Analyzer analyzer;
503	    par_op_ = ParallelOp((MakeSIMTLoop(&analyzer)));
504	  }
505	  auto layout_map = par_op_->InferLayout(T, level);
506	  return layout_map;
507	}
508	// Checks if this copy can be lowered to a Bulk Load (TMA) instruction.
509	// Requires: TMA support, global->shared scope, matching dtypes.
510	bool CopyNode::CheckBulkLoad(Target target, arith::Analyzer *analyzer,
511	                             bool check_last_dim) const {
512	  // 1. arch must have bulk copy support
513	  if (!TargetHasBulkCopy(target))
514	    return false;
515	  // 2. src and dst must be global and shared
516	  if (src.scope() != "global" ||
517	      (dst.scope() != "shared.dyn" && dst.scope() != "shared"))
518	    return false;
519	  // 3. check shape.
520	  // last dim of src * dtype.bits() must be a multiple of 16
521	  // https://docs.nvidia.com/cuda/cuda-driver-api/group__CUDA__TENSOR__MEMORY.html#group__CUDA__TENSOR__MEMORY_1ga7c7d2aaac9e49294304e755e6f341d7
522	  // now we check src (gmem) as tma box dim is deduced from src
523	  if (check_last_dim &&
524	      analyzer->CanProve(
525	          FloorMod(src_range[src_range.size() - 1]->extent * src->dtype.bytes(),
526	                   16) != 0,
527	          arith::ProofStrength::kSymbolicBound)) {
528	    LOG(WARNING)
529	        << "src range must have last dim multiple of 16 for tma bulk load "
530	        << src->name << " range " << src_range[src_range.size() - 1]->extent
531	        << " * " << src->dtype.bytes() << " % 16 != 0";
532	    return false;
533	  }
534	
535	  // 4. src and dst must have the same dtype
536	  if (src->dtype != dst->dtype) {
537	    LOG(WARNING) << "src and dst must have the same dtype for tma load "
538	                 << src->name << " vs. " << dst->name << " dtype " << src->dtype
539	                 << " vs. " << dst->dtype << " will be fallback to normal copy";
540	    return false;
541	  }
542	  return true;
543	}
544	
545	bool CopyNode::CheckBulkCopy1D(const Buffer &global_tensor,
546	                               const Buffer &shared_tensor,
547	                               const Array<Range> &global_range,
548	                               const Array<Range> &shared_range,
549	                               const LayoutMap &layout_map,
550	                               arith::Analyzer *analyzer) const {
551	
552	  // Step 1: check shared is contiguous (linear layout is also contiguous)
553	  bool shared_is_contiguous = true;
554	  if (layout_map.count(shared_tensor)) {
555	    // Check if the layout is linear
556	    Layout existing =
557	        layout_map.Get(shared_tensor).value().as<Layout>().value();
558	    Layout linear_layout = makeLinearLayout(shared_tensor->shape);
559	    shared_is_contiguous = StructuralEqual()(existing, linear_layout);
560	  }
561	  // Step 2: check global is contiguous
562	  bool global_is_contiguous = true;
563	  bool global_not_full_dim_encounter = false;
564	  for (int i = global_range.size() - 1; i >= 0; i--) {
565	    if (!global_not_full_dim_encounter) {
566	      if (!analyzer->CanProve(global_range[i]->extent ==
567	                                      global_tensor->shape[i] &&
568	                                  global_range[i]->min == 0,
569	                              arith::ProofStrength::kSymbolicBound)) {
570	        global_not_full_dim_encounter = true;
571	      }
572	    } else {
573	      if (!analyzer->CanProve(global_range[i]->extent == 1,
574	                              arith::ProofStrength::kSymbolicBound)) {
575	        global_is_contiguous = false;
576	        break;
577	      }
578	    }
579	  }
580	
581	  // Step 3: check element match and no OOB
582	  PrimExpr shared_elements = 1;
583	  for (size_t i = 0; i < shared_range.size(); i++) {
584	    shared_elements *= shared_range[i]->extent;
585	  }
586	  PrimExpr global_elements = 1;
587	  for (size_t i = 0; i < global_range.size(); i++) {
588	    global_elements *= global_range[i]->extent;
589	  }
590	  bool element_match =
591	      analyzer->CanProveEqual(shared_elements, global_elements);
592	
593	  return (shared_is_contiguous && global_is_contiguous && element_match);
594	}
