596	bool CopyNode::CheckBulkLoad1D(Target target, const LayoutMap &layout_map,
597	                               arith::Analyzer *analyzer) const {
598	  if (!CheckBulkLoad(target, analyzer, false))
599	    return false;
600	  auto global_tensor = src;
601	  auto shared_tensor = dst;
602	  auto global_range = src_range;
603	  auto shared_range = dst_range;
604	  return CheckBulkCopy1D(global_tensor, shared_tensor, global_range,
605	                         shared_range, layout_map, analyzer);
