620	// Checks if this copy can be lowered to a Bulk Store (TMA) instruction.
621	// Requires: TMA support, shared->global scope, matching dtypes.
622	bool CopyNode::CheckBulkStore(Target target, arith::Analyzer *analyzer,
623	                              bool check_last_dim) const {
624	  // 1. arch must have bulk copy support
625	  if (!TargetHasBulkCopy(target))
626	    return false;
627	  // 2. src and dst must be shared.dyn and local.fragment
628	  if ((src.scope() != "shared.dyn" && src.scope() != "shared") ||
629	      dst.scope() != "global")
630	    return false;
631	  // 3. check shape.
632	  // last dim of dst * dtype.bits() must be a multiple of 16
633	  // https://docs.nvidia.com/cuda/cuda-driver-api/group__CUDA__TENSOR__MEMORY.html#group__CUDA__TENSOR__MEMORY_1ga7c7d2aaac9e49294304e755e6f341d7
634	  // now we check dst (gmem) as tma box dim is deduced from dst
635	  if (check_last_dim &&
636	      analyzer->CanProve(
637	          FloorMod(dst_range[dst_range.size() - 1]->extent * dst->dtype.bytes(),
638	                   16) != 0,
639	          arith::ProofStrength::kSymbolicBound)) {
640	    LOG(WARNING)
641	        << "dst range must have last dim multiple of 16 for tma bulk store "
642	        << dst->name << " range " << dst_range[dst_range.size() - 1]->extent
643	        << " * " << dst->dtype.bytes() << " % 16 != 0";
644	    return false;
645	  }
646	  // 4. src and dst must have the same dtype
647	  if (src->dtype != dst->dtype) {
648	    LOG(WARNING) << "src and dst must have the same dtype for tma store "
649	                 << src->name << " vs. " << dst->name << " dtype " << src->dtype
650	                 << " vs. " << dst->dtype << " will be fallback to normal copy";
651	    return false;
652	  }
653	  return true;
654	}
