721	// Lowers the copy operation to PTX code by dispatching to specialized lowering
722	// functions.
723	Stmt CopyNode::Lower(const LowerArgs &T, arith::Analyzer *analyzer) const {
724	  Target target = T.target;
725	
726	  using namespace tvm::transform;
727	  PassContext pass_ctx = PassContext::Current();
728	  bool disable_tma_lower =
729	      pass_ctx->GetConfig<Bool>(kDisableTMALower, Bool(false)).value();
730	  auto copy_inst = GetCopyInst(target, disable_tma_lower || GetDisableTMA(),
731	                               T.layout_map, analyzer);
732	  if (copy_inst == CopyInst::kTMemLoad || copy_inst == CopyInst::kTMemStore) {
733	    auto tmem_copy = LowerTmemCopy(T, analyzer);
734	    ICHECK(tmem_copy.defined()) << "Failed to lower tensor memory copy";
735	    return tmem_copy;
736	  } else if (copy_inst == CopyInst::kBulkLoad1D ||
737	             copy_inst == CopyInst::kBulkStore1D) {
738	    auto bulk_copy = LowerBulkCopy1D(T, analyzer, copy_inst);
739	    ICHECK(bulk_copy.defined()) << "Failed to lower bulk load 1d";
740	    return bulk_copy;
741	  } else if (copy_inst == CopyInst::kBulkLoad ||
742	             copy_inst == CopyInst::kBulkStore) {
743	    auto bulk_copy = LowerBulkCopy(T, analyzer, copy_inst);
744	    ICHECK(bulk_copy.defined()) << "Failed to lower bulk load/store";
745	    return bulk_copy;
746	  } else if (copy_inst == CopyInst::kLDSM || copy_inst == CopyInst::kSTSM) {
747	    auto ldsm_copy = LowerLDSMCopy(T, analyzer, copy_inst);
748	    ICHECK(ldsm_copy.defined()) << "Failed to lower ptx matrix copy";
749	    return ldsm_copy;
750	  } else if (copy_inst == CopyInst::kNormal) {
751	    return LowerNormalCopy(T, analyzer);
752	  } else {
753	    LOG(FATAL) << "Unsupported copy inst " << static_cast<int>(copy_inst);
754	  }
755	}
756	
757	// Lowers the copy using standard load/store with loop transformations.
758	Stmt CopyNode::LowerNormalCopy(const LowerArgs &T,
759	                               arith::Analyzer *analyzer) const {
760	  bool is_cpu_target = T.target->GetTargetDeviceType() == kDLCPU;
761	  auto simt_loop = MakeSIMTLoop(analyzer);
762	  auto fused_loop = Downcast<For>(ParallelLoopFuser::Fuse(simt_loop));
763	
764	  auto transformed_loop =
765	      Downcast<For>(ParallelLoopTransformer::Substitute(fused_loop));
766	
767	  For vectorized_thread_loop;
768	  auto par_op = ParallelOp(transformed_loop);
769	
770	  if (is_cpu_target || IsLocalBuffer(src) || IsLocalBuffer(dst)) {
771	    if (IsLocalBuffer(src) && !IsLocalBuffer(dst)) {
772	      LOG(WARNING) << "Copy from local buffer `" << src->name << "` to "
773	                   << dst.scope() << " buffer `" << dst->name
774	                   << "` may cause conflicted write.";
775	    }
776	    vectorized_thread_loop = VectorizeLoop(transformed_loop);
777	    return vectorized_thread_loop;
778	  } else {
779	    std::vector<InferLevel> levels = {InferLevel::kCommon, InferLevel::kStrict,
780	                                      InferLevel::kFree};
781	    for (auto level : levels) {
782	      par_op->InferLayout({T.target,
783	                           T.thread_bounds,
784	                           T.layout_map,
785	                           analyzer,
786	                           false,
787	                           T.buffer_remap,
788	                           {}},
789	                          level);
790	    }
791	    auto loop_layout = par_op->GetLoopLayout();
792	    // Use LowerParallelLoop to handle partitioning, vectorization, and
793	    // predicate
794	    return LowerParallelLoop(par_op->GetRoot(), loop_layout, T.thread_var,
795	                             analyzer, par_op->GetPredicate(T.thread_var));
796	  }
797	}
798	
799	// Lowers copy to LDSM/STSM (warp-level 8x8 matrix) instructions.
800	// Falls back to LowerNormalCopy if hardware constraints are not met.
801	Stmt CopyNode::LowerLDSMCopy(const LowerArgs &T, arith::Analyzer *analyzer,
802	                             CopyInst copy_inst) const {
803	  ICHECK(copy_inst == CopyInst::kLDSM || copy_inst == CopyInst::kSTSM)
804	      << "Invalid copy inst " << static_cast<int>(copy_inst);
805	  bool is_ldmatrix = copy_inst == CopyInst::kLDSM;
806	
807	  // Check no predicates
808	  Array<IterVar> loop_vars = MakeIterVars();
809	  if (loop_vars.size() < 2) {
810	    // cannot support 1-d case
811	    return LowerNormalCopy(T, analyzer);
812	  }
813	  for (const auto &iv : loop_vars)
814	    analyzer->Bind(iv->var, iv->dom);
815	  PrimExpr src_predicate = MakePredicate(analyzer, loop_vars, src->shape, 0);
816	  PrimExpr dst_predicate = MakePredicate(analyzer, loop_vars, dst->shape, 1);
817	  if (src_predicate.defined() || dst_predicate.defined()) {
818	    // stmatrix and ldmatrix can only support no predicate
819	    return LowerNormalCopy(T, analyzer);
820	  }
821	
822	  Buffer shared_tensor = is_ldmatrix ? src : dst;
823	  Buffer local_tensor = is_ldmatrix ? dst : src;
824	
825	  Array<PrimExpr> local_indices = MakeIndices(loop_vars, is_ldmatrix ? 1 : 0);
826	  Fragment local_layout = Downcast<Fragment>(T.layout_map[local_tensor]);
827	  Array<PrimExpr> local_indices_transformed =
828	      local_layout->Forward(local_indices);
829	  local_tensor = T.buffer_remap[local_tensor];
830	  // currently only support 1-d case
831	  if (local_layout->OutputDim() != 1) {
832	    // TMA ldmatrix/stmatrix cannot support non-1-d layout, will be fallback to
833	    // normal copy
834	    return LowerNormalCopy(T, analyzer);
835	  }
836	
837	  Array<PrimExpr> shared_indices = MakeIndices(loop_vars, is_ldmatrix ? 0 : 1);
838	  Array<PrimExpr> shared_indices_transformed = shared_indices;
839	  Layout shared_layout;
840	  if (T.buffer_remap.count(shared_tensor)) {
841	    shared_layout = T.layout_map[shared_tensor];
842	    shared_tensor = T.buffer_remap[shared_tensor];
843	    shared_indices_transformed = shared_layout->Forward(shared_indices);
844	  }
845	
846	  // Check local_layout follows 8x8 layout
847	  // LDSM/STSM instructions require 8x8 matrix fragment layout
848	  // This matches the warp-level matrix multiplication pattern used in tensor
849	  // cores We check both normal and transposed layouts to support different
850	  // access patterns
851	  bool is_transposed;
852	  IterVar col_var = loop_vars[loop_vars.size() - 1];
853	  IterVar row_var = loop_vars[loop_vars.size() - 2];
854	  PrimExpr local_layout_thread_map =
855	      FloorMod(local_layout->ForwardThread(local_indices, std::nullopt), 32);
856	  PrimExpr matrix_8x8_thread_map = makeGemmFragment8x8()->ForwardThread(
857	      {FloorMod(row_var, 8), FloorMod(col_var, 8)}, std::nullopt);
858	  PrimExpr matrix_8x8_thread_map_trans =
859	      makeGemmFragment8x8Transposed()->ForwardThread(
860	          {FloorMod(row_var, 8), FloorMod(col_var, 8)}, std::nullopt);
861	  PrimExpr local_indices_flattened =
862	      local_tensor.OffsetOf(local_indices_transformed).back();
863	  if (analyzer->CanProveEqual(matrix_8x8_thread_map, local_layout_thread_map) &&
864	      IndiceCanVectorize(local_indices_flattened, col_var->var,
865	                         col_var->dom->extent, 2, analyzer)) {
866	    is_transposed = false;
867	  } else if (analyzer->CanProveEqual(matrix_8x8_thread_map_trans,
868	                                     local_layout_thread_map) &&
869	             IndiceCanVectorize(local_indices_flattened, row_var->var,
870	                                row_var->dom->extent, 2, analyzer)) {
871	    is_transposed = true;
872	  } else {
873	    // TMA ldmatrix/stmatrix cannot support non-8x8 layout, will be fallback to
874	    // normal copy
875	    return LowerNormalCopy(T, analyzer);
876	  }
877	  // Check shared_layout is 16 bytes continuous
878	  // LDSM/STSM instructions require 16-byte aligned data (half-precision floats)
879	  // This is a hardware constraint for matrix load/store operations
880	  if (shared_tensor->dtype.bytes() != 2) {
881	    // TMA ldmatrix/stmatrix cannot support non-16 bytes continuous layout, will
882	    // be fallback to normal copy
883	    return LowerNormalCopy(T, analyzer);
884	  }
885	  PrimExpr flattened_indice =
886	      shared_tensor.OffsetOf(shared_indices_transformed).back();
887	  if (!IndiceCanVectorize(flattened_indice, loop_vars.back()->var,
888	                          loop_vars.back()->dom->extent, 8, analyzer)) {
889	    // TMA ldmatrix/stmatrix cannot support non-16 bytes continuous layout, will
890	    // be fallback to normal copy
891	    return LowerNormalCopy(T, analyzer);
892	  }
893	
894	  // Can only support local_range to be a full range
895	  for (size_t i = 0; i < dst_range.size(); i++) {
896	    if (!is_zero(dst_range[i]->min) ||
897	        !analyzer->CanProveEqual(dst_range[i]->extent, dst->shape[i]))
898	      // TMA ldmatrix/stmatrix cannot support non-full range, will be fallback
899	      // to normal copy
900	      return LowerNormalCopy(T, analyzer);
901	  }
902	
903	  // Do the lowering here, try vectorized ldmatrix/stmatrix by 4/2/1
904	  PrimExpr extent = local_tensor->shape[0];
905	  int num = 1;
906	  if (analyzer->CanProveEqual(FloorMod(extent, 8), 0))
907	    num = 4;
908	  else if (analyzer->CanProveEqual(FloorMod(extent, 4), 0))
909	    num = 2;
910	
911	  Array<PrimExpr> args;
912	  const Op &op = is_ldmatrix ? tl::ptx_ldmatrix() : tl::ptx_stmatrix();
913	  args.push_back(static_cast<int>(is_transposed));
914	  args.push_back(num);
915	
916	  // Create shared address with regard to local address
917	  // if not transpose
918	  // coords = Inverse(base + 2 * (thread / 8) % num, warp + (thread % 8) * 4))
919	  // if transpose
920	  // coords = Inverse(base + 2 * (thread / 8) % num + thread % 2, warp + thread
921	  // % 8 / 2)
922	  Var local_iter("i");
923	  Layout inv = local_layout->Inverse();
924	  Array<PrimExpr> shared_coords;
925	  PrimExpr warp = FloorDiv(T.thread_var, 32) * 32;
926	  if (!is_transposed)
927	    shared_coords = inv->Forward(
928	        {local_iter * 2 * num + 2 * FloorMod(FloorDiv(T.thread_var, 8), num),
929	         warp + FloorMod(T.thread_var, 8) * 4});
930	  else
931	    shared_coords = inv->Forward(
932	        {local_iter * 2 * num + 2 * FloorMod(FloorDiv(T.thread_var, 8), num) +
933	             FloorMod(T.thread_var, 2),
934	         warp + FloorDiv(FloorMod(T.thread_var, 8), 2)});
935	  shared_coords.pop_back(); // remove rep
936	  if (shared_layout.defined())
937	    shared_coords = shared_layout->Forward(shared_coords);
938	  PrimExpr shared_addr = shared_tensor.access_ptr(
939	      is_ldmatrix ? 1 : 2, DataType::Handle(), 1,
940	      shared_tensor.OffsetOf(shared_coords).back(), PrimExpr(2 * num));
941	  args.push_back(shared_addr);
942	
943	  if (is_ldmatrix) {
944	    // Can only support same dtype for ldmatrx
945	    if (local_tensor->dtype != shared_tensor->dtype) {
946	      // TMA ldmatrix cannot support different dtype, will be fallback to normal
947	      // copy
948	      return LowerNormalCopy(T, analyzer);
949	    }
950	    PrimExpr local_addr = local_tensor.access_ptr(
951	        2, DataType::Handle(), 1, local_iter * 2 * num, PrimExpr(2 * num));
952	    args.push_back(local_addr);
953	  } else {
954	    for (int i = 0; i < num; i++) {
955	      PrimExpr value0 =
956	          BufferLoad(local_tensor, {local_iter * 2 * num + 2 * i});
957	      PrimExpr value1 =
958	          BufferLoad(local_tensor, {local_iter * 2 * num + 2 * i + 1});
959	      if (local_tensor->dtype != shared_tensor->dtype) {
960	        value0 = Cast(shared_tensor->dtype, value0);
961	        value1 = Cast(shared_tensor->dtype, value1);
962	      }
963	      PrimExpr value_packed =
964	          Call(DataType::Int(32), pack_b16(), {value0, value1});
965	      args.push_back(value_packed);
966	    }
967	  }
968	
969	  auto body = Evaluate(Call(DataType::Handle(), op, args));
970	  For for_node =
971	      For(local_iter, 0, FloorDiv(extent, 2 * num), ForKind::kSerial, body);
972	  for_node = LoopPragmaUnroll(for_node);
973	  auto range = T.thread_bounds;
974	  if (range.defined()) {
975	    auto thread_var = T.thread_var;
976	    auto thread_var_with_offset = thread_var - range->min;
977	    for_node.CopyOnWrite()->body =
978	        Substitute(for_node->body, {{thread_var, thread_var_with_offset}});
979	  }
980	  return for_node;
981	}
