983	// Lowers tensor memory copy operations (tcgen05.ld/st/cp).
984	// Currently only tcgen05.ld is fully supported.
985	Stmt CopyNode::LowerTmemCopy(const LowerArgs &T,
986	                             arith::Analyzer *analyzer) const {
987	  if (src.scope() != "shared.tmem" && dst.scope() != "shared.tmem") {
988	    return Stmt();
989	  }
990	  ICHECK(TargetHasTmem(T.target)) << "Target " << T.target->ToDebugString()
991	                                  << " does not support tensor memory copy";
992	
993	  // Decide copy type
994	  bool is_ld = false; // tcgen05.ld (tensor memory -> register)
995	  bool is_st = false; // tcgen05.st (register -> tensor memory)
996	  bool is_cp = false; // tcgen05.cp (shared memory -> tensor memory)
997	  bool src_needs_pack =
998	      16 == src->dtype.bits(); // if needs .pack::16b when is_ld
999	  bool dst_needs_unpack =
1000	      16 == dst->dtype.bits(); // if needs .unpack::16b when is_st
1001	
1002	  if (src.scope() == "shared.tmem" && IsFragmentBuffer(dst)) {
1003	    is_ld = true;
1004	  } else if (IsFragmentBuffer(src) && dst.scope() == "shared.tmem") {
1005	    is_st = true;
1006	  } else if (src.scope() == "shared.dyn" && dst.scope() == "shared.tmem") {
1007	    is_cp = true;
1008	  } else {
1009	    LOG(FATAL) << "Unsupported tensor memory copy: "
1010	               << "src scope = " << src.scope()
1011	               << ", dst scope = " << dst.scope();
1012	  }
1013	  // Currently tcgen05.cp is not supported
1014	  // TODO (mzw) Support tcgen05.cp
1015	  ICHECK(!is_cp)
1016	      << "Copy from shared memory to tensor memory is not supported yet";
1017	  // Currently tcgen05.st is not supported
1018	  // TODO (mzw) Support tcgen05.st
1019	  ICHECK(!is_st) << "Copy from register to tensor memory is not supported yet";
1020	
1021	  // Extract loop variables and ranges
1022	  Array<IterVar> loop_vars = MakeIterVars();
1023	  ICHECK(loop_vars.size() == 2) << "Only support 2D tensor memory copy, got "
1024	                                << loop_vars.size() << " dimensions";
1025	  for (const auto &iv : loop_vars)
1026	    analyzer->Bind(iv->var, iv->dom);
1027	  PrimExpr src_predicate = MakePredicate(analyzer, loop_vars, src->shape, 0);
1028	  PrimExpr dst_predicate = MakePredicate(analyzer, loop_vars, dst->shape, 1);
1029	  ICHECK(!src_predicate.defined() && !dst_predicate.defined())
1030	      << "Tensor memory copy does not support predicates, got " << src_predicate
1031	      << " and " << dst_predicate;
1032	  ICHECK(is_const_int(loop_vars[0]->dom->min) &&
1033	         is_const_int(loop_vars[0]->dom->extent) &&
1034	         is_const_int(loop_vars[1]->dom->min) &&
1035	         is_const_int(loop_vars[1]->dom->extent))
1036	      << "Tensor memory copy requires loop bounds to be constant integers";
1037	  int64_t logical_row_min = *as_const_int(loop_vars[0]->dom->min);
1038	  int64_t logical_row_extent = *as_const_int(loop_vars[0]->dom->extent);
1039	  int64_t logical_col_min = *as_const_int(loop_vars[1]->dom->min);
1040	  int64_t logical_col_extent = *as_const_int(loop_vars[1]->dom->extent);
1041	
1042	  // Extract thread bounds
1043	  constexpr int WARP_SIZE = 32; // Set to 32 since only sm100 is supported
1044	  constexpr int WARPGROUP_SIZE = 4 * WARP_SIZE;
1045	  ICHECK(is_const_int(T.thread_bounds->extent))
1046	      << "Tensor memory copy requires thread_bounds->extent (num_threads) to "
1047	         "be constant integers";
1048	  int num_threads = *as_const_int(T.thread_bounds->extent);
1049	  ICHECK(analyzer->CanProveEqual(FloorMod(T.thread_bounds->min, WARPGROUP_SIZE),
1050	                                 0) &&
1051	         num_threads % WARPGROUP_SIZE == 0)
1052	      << "Tensor memory copy requires thread bounds to be aligned to "
1053	         "warpgroups, but found "
1054	      << "thread range = " << T.thread_bounds;
1055	
1056	  // TODO (mzw) Buffer remap for shared.dyn when is_cp is true?
1057	
1058	  // Retrieve layout
1059	  ICHECK(T.layout_map.count(src))
1060	      << "Source buffer " << src->name << " does not have a layout specified";
1061	  ICHECK(T.layout_map.count(dst)) << "Destination buffer " << dst->name
1062	                                  << " does not have a layout specified";
1063	  Layout src_layout = T.layout_map[src];
1064	  Fragment dst_layout = Downcast<Fragment>(T.layout_map[dst]);
1065	
1066	  // Check layout
1067	  Array<PrimExpr> logical_indices = MakeIndices(loop_vars, 0);
1068	  Array<PrimExpr> phy_indices =
1069	      src_layout->Forward(logical_indices); // "phy" for "physical"
1070	
1071	  // Analyse the range of tmem_phy_row and tmem_phy_col
1072	  arith::ConstIntBound phy_row_bounds =
1073	      analyzer->const_int_bound(phy_indices[0]);
1074	  arith::ConstIntBound phy_col_bounds =
1075	      analyzer->const_int_bound(phy_indices[1]);
1076	  int tmem_phy_row_min = phy_row_bounds->min_value;
1077	  int tmem_phy_row_max = phy_row_bounds->max_value;
1078	  int tmem_phy_col_min = phy_col_bounds->min_value;
1079	  int tmem_phy_col_max = phy_col_bounds->max_value;
1080	  int tmem_phy_row_extent = tmem_phy_row_max - tmem_phy_row_min + 1;
1081	  int tmem_phy_col_extent = tmem_phy_col_max - tmem_phy_col_min + 1;
1082	  Range row_dom = Range(tmem_phy_row_min, tmem_phy_row_max + 1);
1083	  Range col_dom = Range(tmem_phy_col_min, tmem_phy_col_max + 1);
1084	
1085	  bool have_succeeded = false;
1086	  Stmt body;
1087	
1088	  auto try_tcgen05_instruction = [&](Tcgen05Meta meta) {
1089	    if (have_succeeded) {
1090	      return;
1091	    }
1092	    if (tmem_phy_row_min != 0 || tmem_phy_row_max != 127) {
1093	      return;
1094	    }
1095	    if (tmem_phy_col_min % meta.width != 0 ||
1096	        (tmem_phy_col_max + 1) % meta.width != 0) {
1097	      return;
1098	    }
1099	
1100	    for (int num_useful_wgs = num_threads / WARPGROUP_SIZE; num_useful_wgs >= 1;
1101	         num_useful_wgs--) {
1102	      int num_useful_threads = num_useful_wgs * WARPGROUP_SIZE;
1103	      auto [is_success, target_frag, num_chunks_each_wg] = expandTcgen05Layout(
1104	          meta, tmem_phy_col_extent, num_useful_threads, row_dom, col_dom);
1105	      if (!is_success) {
1106	        continue;
1107	      }
1108	
1109	      PrimExpr target_thread =
1110	          target_frag->ForwardThread(phy_indices, std::nullopt);
1111	      PrimExpr dst_thread =
1112	          dst_layout->ForwardThread(logical_indices, std::nullopt);
1113	      if (!analyzer->CanProveEqual(target_thread, dst_thread)) {
1114	        continue;
1115	      }
1116	      PrimExpr target_reg = target_frag->Forward(phy_indices)[0];
1117	      PrimExpr dst_reg = dst_layout->Forward(logical_indices)[0];
1118	      if (!analyzer->CanProveEqual(target_reg, dst_reg)) {
1119	        continue;
1120	      }
1121	
1122	      // All checks passed, we can use this instruction
1123	      PrimExpr relative_wg_idx =
1124	          FloorDiv(Sub(T.thread_var, T.thread_bounds->min), WARPGROUP_SIZE);
1125	      PrimExpr col_offset =
1126	          num_useful_threads == WARPGROUP_SIZE
1127	              ? PrimExpr(0)
1128	              : relative_wg_idx * (num_chunks_each_wg * meta.width);
1129	      have_succeeded = true;
1130	      Array<PrimExpr> args;
1131	      const char *bool_str = src_needs_pack ? "true" : "false";
1132	      args.push_back(StringImm(meta.intrinsics_name + "<" +
1133	                               std::to_string(num_chunks_each_wg) + ", " +
1134	                               bool_str + ">"));
1135	      args.push_back(
1136	          BufferLoad(src, {(int)logical_row_min,
1137	                           (int)logical_col_min})); // Will be translated later
1138	                                                    // in lower_shared_tmem pass
1139	      args.push_back(col_offset);
1140	      args.push_back(dst.access_ptr(2, DataType::Handle(), 1, 0,
1141	                                    PrimExpr(tmem_phy_col_extent)));
1142	
1143	      Stmt call =
1144	          Evaluate(Call(DataType::Handle(), builtin::call_extern(), args));
1145	      if (num_useful_threads != num_threads) {
1146	        body =
1147	            IfThenElse(T.thread_var < T.thread_bounds->min + num_useful_threads,
1148	                       call, // No-op for unused threads
1149	                       Stmt());
1150	      } else {
1151	        body = call;
1152	      }
1153	      break;
1154	    }
1155	  };
1156	
1157	  try_tcgen05_instruction(getTcgen05Meta_32dp32b());
1158	  try_tcgen05_instruction(getTcgen05Meta_32dp64b());
1159	  try_tcgen05_instruction(getTcgen05Meta_32dp128b());
1160	  try_tcgen05_instruction(getTcgen05Meta_32dp256b());
1161	
1162	  ICHECK(have_succeeded) << "Failed to find a suitable instruction for "
1163	                            "tcgen05.ld. Check your layout.";
1164	
1165	  return body;
1166	}
