1168	// Lowers copy to a bulk TMA (Tensor Memory Accelerator) transfer.
1169	// Falls back to LowerNormalCopy if preconditions are not satisfied.
1170	Stmt CopyNode::LowerBulkCopy(const LowerArgs &T, arith::Analyzer *analyzer,
1171	                             CopyInst copy_inst) const {
1172	  ICHECK(copy_inst == CopyInst::kBulkLoad || copy_inst == CopyInst::kBulkStore)
1173	      << "Invalid copy inst " << static_cast<int>(copy_inst);
1174	  bool is_load = copy_inst == CopyInst::kBulkLoad;
1175	  Buffer global_tensor = is_load ? src : dst;
1176	  Buffer shared_tensor = is_load ? dst : src;
1177	  Array<Range> global_range = is_load ? src_range : dst_range;
1178	  Array<Range> shared_range = is_load ? dst_range : src_range;
1179	  // TMA bulk copy cannot support a non-swizzled global layout, will be fallback
1180	  // to normal copy
1181	  if (T.layout_map.count(global_tensor)) {
1182	    LOG(WARNING) << "TMA bulk copy cannot support a non-swizzled global "
1183	                    "layout, fallback to normal copy.";
1184	    return LowerNormalCopy(T, analyzer);
1185	  }
1186	
1187	  // linear layout must be computed before remapping
1188	  auto linear_layout = ComputeLinearLayout(shared_tensor);
1189	
1190	  Array<PrimExpr> shared_indices;
1191	  for (auto r : shared_range)
1192	    shared_indices.push_back(r->min);
1193	  std::vector<PrimExpr> shared_strides;
1194	  PrimExpr shared_stride = 1;
1195	  for (size_t i = 0; i < shared_tensor->shape.size(); i++) {
1196	    auto s = shared_tensor->shape[shared_tensor->shape.size() - i - 1];
1197	    shared_strides.insert(shared_strides.begin(), shared_stride);
1198	    shared_stride *= s;
1199	  }
1200	
1201	  Array<PrimExpr> global_indices;
1202	  for (auto r : global_range) {
1203	    global_indices.push_back(r->min);
1204	  }
1205	  std::vector<PrimExpr> global_strides;
1206	  PrimExpr global_stride = 1;
1207	  for (size_t i = 0; i < global_tensor->shape.size(); i++) {
1208	    auto s = global_tensor->shape[global_tensor->shape.size() - i - 1];
1209	    global_strides.insert(global_strides.begin(), global_stride);
1210	    global_stride *= s;
1211	  }
1212	
1213	  ICHECK(shared_strides.size() == shared_indices.size())
1214	      << "shared_strides.size() != shared_indices.size()"
1215	      << shared_strides.size() << " " << shared_indices.size();
1216	  PrimExpr shared_offset = 0;
1217	  for (size_t i = 0; i < shared_indices.size(); i++) {
1218	    shared_offset += shared_indices[i] * shared_strides[i];
1219	  }
1220	  PrimExpr global_offset = 0;
1221	  for (size_t i = 0; i < global_indices.size(); i++) {
1222	    global_offset += global_indices[i] * global_strides[i];
1223	  }
1224	
1225	  TMADesc desc;
1226	  // Verify copy rank
1227	  desc.rank = global_tensor->shape.size();
1228	  ICHECK(desc.rank >= 1 && desc.rank <= 5) << desc.rank;
1229	
1230	  // Verify datatype
1231	  ICHECK(global_tensor->dtype == shared_tensor->dtype)
1232	      << "Copy between buffer " << global_tensor->name << " and "
1233	      << shared_tensor->name << " with different data type "
1234	      << global_tensor->dtype << " and " << shared_tensor->dtype;
1235	
1236	  desc.data_type = to_CUtensorMapDataType(global_tensor->dtype);
1237	
1238	  // Global Tensor Shape and Stride
1239	  desc.global_addr = global_tensor->data;
1240	  desc.global_shape = ReverseArray(global_tensor->shape);
1241	  Array<PrimExpr> global_coords =
1242	      ReverseArray(global_range.Map([](Range r) { return r->min; }));
1243	  if (!global_tensor->strides.empty()) {
1244	    desc.global_stride = ReverseArray(global_tensor->strides);
1245	  } else {
1246	    // Create stride from shape
1247	    PrimExpr stride = 1;
1248	    desc.global_stride.reserve(desc.rank);
1249	    for (size_t i = 0; i < desc.rank; i++) {
1250	      desc.global_stride.push_back(stride);
1251	      stride *= desc.global_shape[i];
1252	    }
1253	  }
1254	  // The first stride element should be 1
1255	  ICHECK(is_one(desc.global_stride[0])) << desc.global_stride;
1256	  // Make global stride in bytes
1257	  desc.global_stride = desc.global_stride.Map([&](PrimExpr e) {
1258	    return cast(DataType::Int(64), e) * global_tensor->dtype.bytes();
1259	  });
1260	  for (size_t i{1}; i < desc.global_stride.size(); i++) {
1261	    auto stride = desc.global_stride[i].as<IntImmNode>();
1262	    if (stride != nullptr) {
1263	      // otherwise, the stride is symbolic, we need to check in future with
1264	      // assumptions
1265	      if (stride->value % 16 != 0 || stride->value >= (1ULL << 40)) {
1266	        LOG(WARNING) << "TMA bulk copy cannot support a global stride of "
1267	                     << desc.global_stride[i] << ", fallback to normal copy.";
1268	        return LowerNormalCopy(T, analyzer);
1269	      }
1270	    }
1271	  }
1272	
1273	  // Smem Box
1274	  // check smem range and global range is legal
1275	  auto s_range_idx = 0;
1276	  for (size_t i = 0; i < global_range.size(); i++) {
1277	    auto g_range = global_range[i];
1278	    if (is_one(g_range->extent)) {
1279	      continue;
1280	    }
1281	    // skip one range if it is 1
1282	    // in case of global range is [128, 64], while shared range is [1, 128, 64]
1283	    // A_shared[0, :, :].
1284	    while (is_one(shared_range[s_range_idx]->extent) &&
1285	           s_range_idx < shared_range.size()) {
1286	      s_range_idx++;
1287	    }
1288	    if (s_range_idx >= shared_range.size()) {
1289	      LOG(FATAL) << "TMA bulk copy cannot support a global range of "
1290	                 << global_range << ", shared_range " << shared_range;
1291	    }
1292	    auto s_range = shared_range[s_range_idx];
1293	    s_range_idx++;
1294	
1295	    ICHECK(StructuralEqual()(g_range->extent, s_range->extent))
1296	        << global_tensor->name << "[" << i << "] is illegal, "
1297	        << global_tensor->name << "[" << i << "] = " << g_range->extent << ", "
1298	        << shared_tensor->name << "[" << s_range_idx
1299	        << "] = " << s_range->extent;
1300	  }
1301	  // TODO(lei): find a much smarter way to deduce smem box dim
1302	  // instead of using global_range
1303	  desc.smem_box =
1304	      ReverseArray(global_range.Map([](Range r) { return r->extent; }));
1305	
1306	  desc.smem_stride = Array<PrimExpr>(desc.rank, PrimExpr(1));
1307	  // L2 & OOB
1308	  desc.l2_promotion = static_cast<int>(CU_TENSOR_MAP_L2_PROMOTION_L2_128B);
1309	  desc.oob_fill = static_cast<int>(CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
1310	
1311	  // Detect smem layout
1312	  // Shared memory swizzling is crucial for TMA performance
1313	  // It determines how data is arranged in shared memory banks to minimize bank
1314	  // conflicts Different swizzle patterns (32B, 64B, 128B) offer different
1315	  // trade-offs between access efficiency and memory usage
1316	  desc.interleave = static_cast<int>(CU_TENSOR_MAP_INTERLEAVE_NONE);
1317	  Layout shared_layout;
1318	  if (T.layout_map.count(shared_tensor)) {
1319	    shared_layout = T.layout_map.at(shared_tensor);
1320	    ICHECK(T.buffer_remap.count(shared_tensor))
1321	        << "shared_tensor: " << shared_tensor->name
1322	        << " not found in buffer_remap";
1323	    shared_tensor = T.buffer_remap.at(shared_tensor);
1324	  }
1325	  if (!shared_layout.defined()) {
1326	    desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_NONE);
1327	  } else if (StructuralEqual()(shared_layout, linear_layout)) {
1328	    desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_NONE);
1329	  } else {
1330	    ICHECK(shared_layout->InputDim() == 2) << "Cannot detect TMA layout.";
1331	    auto stride = as_const_int(shared_layout->InputShape()[0]);
1332	    auto continuous = as_const_int(shared_layout->InputShape()[1]);
1333	    ICHECK(stride != nullptr && continuous != nullptr);
1334	    // We also need to check if the shape satisfies the following doc:
1335	    // https://docs.nvidia.com/cuda/cuda-driver-api/group__CUDA__TENSOR__MEMORY.html#group__CUDA__TENSOR__MEMORY_1ga7c7d2aaac9e49294304e755e6f341d7
1336	    if (StructuralEqual()(shared_layout, makeQuarterBankSwizzleLayout(
1337	                                             *stride, *continuous,
1338	                                             shared_tensor->dtype.bits()))) {
1339	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_32B);
1340	    } else if (StructuralEqual()(
1341	                   shared_layout,
1342	                   makeHalfBankSwizzleLayout(*stride, *continuous,
1343	                                             shared_tensor->dtype.bits()))) {
1344	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_64B);
1345	    } else if (StructuralEqual()(
1346	                   shared_layout,
1347	                   makeFullBankSwizzleLayout(*stride, *continuous,
1348	                                             shared_tensor->dtype.bits()))) {
1349	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_128B);
1350	    } else if (StructuralEqual()(
1351	                   shared_layout,
1352	                   makeGemmABLayoutPadded(*stride, *continuous,
1353	                                          shared_tensor->dtype.bits()))) {
1354	      LOG(WARNING) << "Bulk copy cannot support a padded layout for src: "
1355	                   << src->name << ", dst: " << dst->name
1356	                   << ", fallback to normal copy";
1357	      return LowerNormalCopy(T, analyzer);
1358	    } else {
1359	      LOG(WARNING) << "Came across unsupported swizzle layout for src: "
1360	                   << src->name << ", dst: " << dst->name
1361	                   << ", fallback to normal copy";
1362	      return LowerNormalCopy(T, analyzer);
1363	    }
1364	  }
1365	
1366	  auto inner_box_dim = as_const_int(desc.smem_box[0]);
1367	  if (inner_box_dim == nullptr) {
1368	    LOG(WARNING) << "inner_box_dim " << desc.smem_box[0]
1369	                 << " can only be a constant integer for TMA bulk copy, "
1370	                    "fallback to normal copy";
1371	    return LowerNormalCopy(T, analyzer);
1372	  }
1373	  int instruction_dim = *inner_box_dim;
1374	  if (desc.swizzle == static_cast<int>(CU_TENSOR_MAP_SWIZZLE_64B)) {
1375	    instruction_dim = 64 / src->dtype.bytes();
1376	  } else if (desc.swizzle == static_cast<int>(CU_TENSOR_MAP_SWIZZLE_128B)) {
1377	    instruction_dim = 128 / src->dtype.bytes();
1378	  }
1379	  if (instruction_dim > 256) {
1380	    // smem_box dim must be in [0, 256]
1381	    // if is 512, we need to split the copy into two parts
1382	    ICHECK((*inner_box_dim) % 256 == 0)
1383	        << "inner_box_dim: " << *inner_box_dim << " is not divisible by 256";
1384	    instruction_dim = 256;
1385	  }
1386	  ICHECK((*inner_box_dim) % instruction_dim == 0)
1387	      << "inner_box_dim: " << *inner_box_dim
1388	      << " is not divisible by instruction_dim: " << instruction_dim;
1389	  desc.smem_box.Set(0, PrimExpr(instruction_dim));
1390	
1391	  int inner_box_dim_ = instruction_dim * shared_tensor->dtype.bytes();
1392	
1393	  // Check inner_box_dim_ for each swizzle type in a cleaner way
1394	  struct SwizzleCheck {
1395	    int swizzle;
1396	    int max_dim;
1397	  };
1398	  static const std::vector<SwizzleCheck> swizzle_checks = {
1399	      {static_cast<int>(CU_TENSOR_MAP_SWIZZLE_32B), 32},
1400	      {static_cast<int>(CU_TENSOR_MAP_SWIZZLE_64B), 64},
1401	      {static_cast<int>(CU_TENSOR_MAP_SWIZZLE_128B), 128},
1402	  };
1403	  for (const auto &check : swizzle_checks) {
1404	    if (desc.swizzle == check.swizzle && inner_box_dim_ > check.max_dim) {
1405	      LOG(WARNING) << "TMA bulk copy cannot support a swizzled global layout "
1406	                      "with inner_box_dim_ > "
1407	                   << check.max_dim << ", will be fallback to normal copy";
1408	      return LowerNormalCopy(T, analyzer);
1409	    }
1410	  }
1411	
1412	  Call create_descriptor =
1413	      Call(DataType::Handle(), create_tma_descriptor(), desc.EncodeCallArgs());
1414	
1415	  Array<PrimExpr> args;
1416	  args.reserve(desc.rank + 4);
1417	  args.push_back(create_descriptor);
1418	  if (is_load)
1419	    args.push_back(0); // mbarrier id placeholder
1420	  auto op = is_load ? tma_load() : tma_store();
1421	
1422	  Stmt tma_copy;
1423	  PrimExpr total_elements = 1;
1424	  for (auto e : desc.smem_box)
1425	    total_elements *= e;
1426	
1427	  if ((*inner_box_dim) != instruction_dim) {
1428	    Var loop_var("i");
1429	    int loop_extent = (*inner_box_dim) / instruction_dim;
1430	
1431	    PrimExpr shared_addr = shared_tensor.access_ptr(
1432	        is_load ? 2 : 1, DataType::Handle(), 1,
1433	        shared_offset + total_elements * loop_var, total_elements);
1434	    args.push_back(shared_addr);
1435	    global_coords.Set(0, global_coords[0] + instruction_dim * loop_var);
1436	    for (auto coord : global_coords)
1437	      args.push_back(coord);
1438	    int need_reduce = 0;
1439	    if (!is_load)
1440	      args.push_back(need_reduce);
1441	    args.push_back(GetEvictionPolicy());
1442	    tma_copy = For(loop_var, 0, loop_extent, ForKind::kUnrolled,
1443	                   Evaluate(Call(DataType::Handle(), op, args)));
1444	  } else {
1445	    PrimExpr shared_addr = shared_tensor.access_ptr(
1446	        is_load ? 2 : 1, DataType::Handle(), 1, shared_offset, total_elements);
1447	    args.push_back(shared_addr);
1448	    for (auto coord : global_coords)
1449	      args.push_back(coord);
1450	    int need_reduce = 0;
1451	    if (!is_load)
1452	      args.push_back(need_reduce);
1453	    args.push_back(GetEvictionPolicy());
1454	    tma_copy = Evaluate(Call(DataType::Handle(), op, args));
1455	  }
1456	  tma_copy = IfThenElse(EQ(T.thread_var, T.thread_bounds->min), tma_copy);
1457	
1458	  return tma_copy;
1459	}
1460	
1461	Stmt CopyNode::LowerBulkCopy1D(const LowerArgs &T, arith::Analyzer *analyzer,
1462	                               CopyInst copy_inst) const {
1463	  ICHECK(copy_inst == CopyInst::kBulkLoad1D ||
1464	         copy_inst == CopyInst::kBulkStore1D);
1465	
1466	  // Add 1D TMA copy when the global and shared memory is contiguous
1467	  // Check if shared_tensor->name is present in T.buffer_var_gemm
1468	  // (Array<PrimExpr>) to avoid use 1D TMA copy for swizzled layout
1469	  bool is_load = copy_inst == CopyInst::kBulkLoad1D;
1470	  auto shared_range = is_load ? dst_range : src_range;
1471	  auto global_range = is_load ? src_range : dst_range;
1472	  auto shared_tensor = is_load ? dst : src;
1473	  auto global_tensor = is_load ? src : dst;
1474	
1475	  PrimExpr shared_elements = 1;
1476	  for (size_t i = 0; i < shared_range.size(); i++) {
1477	    shared_elements *= shared_range[i]->extent;
1478	  }
1479	
1480	  std::vector<PrimExpr> shared_strides;
1481	  PrimExpr shared_stride = 1;
1482	  for (size_t i = 0; i < shared_tensor->shape.size(); i++) {
1483	    auto s = shared_tensor->shape[shared_tensor->shape.size() - i - 1];
1484	    shared_strides.insert(shared_strides.begin(), shared_stride);
1485	    shared_stride *= s;
1486	  }
1487	
1488	  Array<PrimExpr> shared_indices;
1489	  for (auto r : shared_range)
1490	    shared_indices.push_back(r->min);
1491	
1492	  Array<PrimExpr> global_indices;
1493	  for (auto r : global_range) {
1494	    global_indices.push_back(r->min);
1495	  }
1496	  std::vector<PrimExpr> global_strides;
1497	  PrimExpr global_stride = 1;
1498	  for (size_t i = 0; i < global_tensor->shape.size(); i++) {
1499	    auto s = global_tensor->shape[global_tensor->shape.size() - i - 1];
1500	    global_strides.insert(global_strides.begin(), global_stride);
1501	    global_stride *= s;
1502	  }
1503	
1504	  PrimExpr global_offset = 0;
1505	  for (size_t i = 0; i < global_indices.size(); i++) {
1506	    global_offset += global_indices[i] * global_strides[i];
1507	  }
1508	
1509	  PrimExpr shared_offset = 0;
1510	  for (size_t i = 0; i < shared_indices.size(); i++) {
1511	    shared_offset += shared_indices[i] * shared_strides[i];
1512	  }
1513	
1514	  PrimExpr elements = analyzer->Simplify(shared_elements);
1515	  PrimExpr shared_addr = shared_tensor.access_ptr(
1516	      is_load ? 2 : 1, DataType::Handle(), 1, shared_offset, elements);
1517	  PrimExpr global_addr = global_tensor.access_ptr(
1518	      is_load ? 1 : 2, DataType::Handle(), 1, global_offset, elements);
1519	  Stmt tma_copy;
1520	  if (is_load) {
1521	    // the zero is a placeholder for mbarrier ids
1522	    tma_copy = Evaluate(
1523	        Call(DataType::Handle(), tma_load(),
1524	             {shared_addr, global_addr, 0,
1525	              elements * shared_tensor->dtype.bytes(), GetEvictionPolicy()}));
1526	  } else {
1527	    int need_reduce = 0;
1528	    tma_copy = Evaluate(
1529	        Call(DataType::Handle(), tma_store(),
1530	             {global_addr, shared_addr, elements * shared_tensor->dtype.bytes(),
1531	              need_reduce, GetEvictionPolicy()}));
1532	  }
1533	  tma_copy = IfThenElse(EQ(T.thread_var, T.thread_bounds->min), tma_copy);
1534	  return tma_copy;
1535	}
1536	// Encodes the TMA descriptor into an array of PrimExpr for
1537	// create_tma_descriptor().
1538	Array<PrimExpr> TMADesc::EncodeCallArgs() const {
1539	  Array<PrimExpr> args;
1540	  args.reserve(rank * 4 + 7);
1541	
1542	  args.push_back(data_type);
1543	  args.push_back(static_cast<int>(rank));
1544	  args.push_back(global_addr);
1545	  for (auto e : global_shape)
1546	    args.push_back(e);
1547	  for (auto e : global_stride)
1548	    args.push_back(e);
1549	  for (auto e : smem_box)
1550	    args.push_back(e);
1551	  for (auto e : smem_stride)
1552	    args.push_back(e);
1553	  args.push_back(interleave);
1554	  args.push_back(swizzle);
1555	  args.push_back(l2_promotion);
1556	  args.push_back(oob_fill);
1557	
1558	  return args;
1559	}
1560	
1561	// Constructs a Conv2DIm2ColOp node from call arguments.
1562	// args: src, dst, nhw_step, c_step, kernel, stride, dilation, padding,
1563	// eviction_policy
1564	Conv2DIm2ColOp::Conv2DIm2ColOp(Array<PrimExpr> args,
1565	                               Map<String, ObjectRef> annotations) {
1566	  ObjectPtr<Conv2DIm2ColOpNode> node =
1567	      tvm::ffi::make_object<Conv2DIm2ColOpNode>();
1568	  node->srcRegion_ = NormalizeToBufferRegion(args[0]);
1569	  node->dstRegion_ = NormalizeToBufferRegion(args[1]);
1570	  node->src_ = node->srcRegion_->buffer;
1571	  node->dst_ = node->dstRegion_->buffer;
1572	  node->nhw_step_ = args[2];
1573	  node->c_step_ = args[3];
1574	  node->kernel_ = args[4].as<IntImm>().value()->value;
1575	  node->stride_ = args[5].as<IntImm>().value()->value;
1576	  node->dilation_ = args[6].as<IntImm>().value()->value;
1577	  node->padding_ = args[7].as<IntImm>().value()->value;
1578	  node->eviction_policy_ = args[8].as<IntImm>().value()->value;
1579	  data_ = std::move(node);
1580	}
1581	
1582	// Creates a shallow copy of this Conv2DIm2ColOpNode.
1583	TileOperator Conv2DIm2ColOpNode::Clone() const {
1584	  auto op = tvm::ffi::make_object<Conv2DIm2ColOpNode>(*this);
1585	  return Conv2DIm2ColOp(op);
1586	}
1587	
1588	// Lowers Conv2D im2col into a TMA-backed PTX sequence for Hopper.
1589	Stmt Conv2DIm2ColOpNode::Lower(const LowerArgs &T,
1590	                               arith::Analyzer *analyzer) const {
1591	  ICHECK(TargetIsHopper(T.target));
1592	  ICHECK(src_.scope() == "global" &&
1593	         (dst_.scope() == "shared.dyn" || dst_.scope() == "shared"));
1594	  ICHECK(src_->shape.size() == 4);
1595	  ICHECK(dst_->shape.size() == 2);
1596	  ICHECK(src_->dtype == dst_->dtype);
1597	  Layout shared_layout;
1598	  if (T.layout_map.count(dst_)) {
1599	    shared_layout = T.layout_map[dst_];
1600	  }
1601	
1602	  TMAIm2ColDesc desc;
1603	  desc.rank = src_->shape.size();
1604	  desc.data_type = to_CUtensorMapDataType(src_->dtype);
1605	  desc.global_addr = src_->data;
1606	  desc.global_shape = ReverseArray(src_->shape);
1607	
1608	  if (!src_->strides.empty()) {
1609	    desc.global_stride = ReverseArray(src_->strides);
1610	  } else {
1611	    // Create stride from shape
1612	    PrimExpr stride = 1;
1613	    desc.global_stride.reserve(desc.rank);
1614	    for (size_t i = 0; i < desc.rank; i++) {
1615	      desc.global_stride.push_back(stride);
1616	      stride *= desc.global_shape[i];
1617	    }
1618	  }
1619	  // The first stride element should be 1
1620	  ICHECK(is_one(desc.global_stride[0])) << desc.global_stride;
1621	  // Make global stride in bytes
1622	  desc.global_stride = desc.global_stride.Map([&](PrimExpr e) {
1623	    return cast(DataType::Int(64), e) * src_->dtype.bytes();
1624	  });
1625	  desc.elem_stride = {1, stride_, stride_, 1};
1626	  desc.lower_corner = {-padding_, -padding_};
1627	  desc.upper_corner = {-padding_, -padding_};
1628	  desc.smem_box_pixel = Downcast<IntImm>(dst_->shape[0])->value;
1629	  desc.smem_box_channel = Downcast<IntImm>(dst_->shape[1])->value;
1630	  desc.l2_promotion = static_cast<int>(CU_TENSOR_MAP_L2_PROMOTION_L2_128B);
1631	  desc.oob_fill = static_cast<int>(CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
1632	  desc.interleave = static_cast<int>(CU_TENSOR_MAP_INTERLEAVE_NONE);
1633	  if (!shared_layout.defined()) {
1634	    desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_NONE);
1635	  } else {
1636	    ICHECK(shared_layout->InputDim() == 2) << "Cannot detect TMA layout.";
1637	    auto stride = as_const_int(shared_layout->InputShape()[0]);
1638	    auto continuous = as_const_int(shared_layout->InputShape()[1]);
1639	    ICHECK(stride != nullptr && continuous != nullptr);
1640	
1641	    if (StructuralEqual()(shared_layout,
1642	                          makeQuarterBankSwizzleLayout(*stride, *continuous,
1643	                                                       dst_->dtype.bits()))) {
1644	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_32B);
1645	    } else if (StructuralEqual()(shared_layout, makeHalfBankSwizzleLayout(
1646	                                                    *stride, *continuous,
1647	                                                    dst_->dtype.bits()))) {
1648	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_64B);
1649	    } else if (StructuralEqual()(shared_layout, makeFullBankSwizzleLayout(
1650	                                                    *stride, *continuous,
1651	                                                    dst_->dtype.bits()))) {
1652	      desc.swizzle = static_cast<int>(CU_TENSOR_MAP_SWIZZLE_128B);
1653	    } else {
1654	      LOG(FATAL) << "Cannot detect TMA layout.";
1655	    }
1656	  }
1657	
1658	  Call create_desc = Call(DataType::Handle(), create_tma_im2col_descriptor(),
1659	                          desc.EncodeCallArgs());
1660	
1661	  Array<PrimExpr> global_coords; // c, w, h, n
1662	  Array<PrimExpr> image_offset;  // w, h
1663	  global_coords.reserve(desc.rank);
1664	
1665	  ICHECK(analyzer->CanProveEqual(
1666	      FloorMod(desc.global_shape[0], desc.smem_box_channel), 0))
1667	      << "Currently can only support divisible channel case";
1668	
1669	  global_coords.push_back(
1670	      FloorMod(c_step_ * desc.smem_box_channel, desc.global_shape[0]));
1671	  image_offset.push_back(
1672	      dilation_ *
1673	      FloorMod(FloorDiv(c_step_ * desc.smem_box_channel, desc.global_shape[0]),
1674	               kernel_));
1675	  image_offset.push_back(dilation_ * FloorDiv(c_step_ * desc.smem_box_channel,
1676	                                              desc.global_shape[0] * kernel_));
1677	
1678	  PrimExpr h_dim =
1679	      FloorDiv(src_->shape[1] + 2 * padding_ - (kernel_ - 1) * dilation_ - 1,
1680	               stride_) +
1681	      1;
1682	  PrimExpr w_dim =
1683	      FloorDiv(src_->shape[2] + 2 * padding_ - (kernel_ - 1) * dilation_ - 1,
1684	               stride_) +
1685	      1;
1686	  global_coords.push_back(
1687	      stride_ * FloorMod(nhw_step_ * desc.smem_box_pixel, w_dim) - padding_);
1688	  global_coords.push_back(
1689	      stride_ *
1690	          FloorMod(FloorDiv(nhw_step_ * desc.smem_box_pixel, w_dim), h_dim) -
1691	      padding_);
1692	  global_coords.push_back(
1693	      FloorDiv(nhw_step_ * desc.smem_box_pixel, w_dim * h_dim));
1694	
1695	  Array<PrimExpr> args;
1696	  args.reserve(desc.rank * 2 + 2);
1697	  args.push_back(create_desc);
1698	  args.push_back(0); // mbar placeholder
1699	  auto dst_buffer = T.buffer_remap.count(dst_) ? T.buffer_remap[dst_] : dst_;
1700	  auto shared_addr = dst_buffer.access_ptr(2);
1701	  args.push_back(shared_addr);
1702	  for (auto coord : global_coords)
1703	    args.push_back(coord);
1704	  for (auto offset : image_offset)
1705	    args.push_back(offset);
1706	  args.push_back(this->eviction_policy_);
1707	  Stmt tma_copy =
1708	      IfThenElse(EQ(T.thread_var, T.thread_bounds->min),
1709	                 Evaluate(Call(DataType::Handle(), tma_load_im2col(), args)));
1710	  return tma_copy;
1711	}
1712	
1713	// Encodes the TMA im2col descriptor for create_tma_im2col_descriptor().
1714	Array<PrimExpr> TMAIm2ColDesc::EncodeCallArgs() const {
1715	  Array<PrimExpr> args;
1716	  args.reserve(rank * 5 + 5);
1717	
1718	  args.push_back(data_type);
1719	  args.push_back(static_cast<int>(rank));
1720	  args.push_back(global_addr);
1721	  for (auto e : global_shape)
1722	    args.push_back(e);
1723	  for (auto e : global_stride)
1724	    args.push_back(e);
1725	  for (auto e : elem_stride)
1726	    args.push_back(e);
1727	  for (auto e : lower_corner)
1728	    args.push_back(e);
1729	  for (auto e : upper_corner)
1730	    args.push_back(e);
1731	  args.push_back(smem_box_pixel);
1732	  args.push_back(smem_box_channel);
1733	  args.push_back(interleave);
1734	  args.push_back(swizzle);
1735	  args.push_back(l2_promotion);
1736	  args.push_back(oob_fill);
1737	
1738	  return args;
1739	}
1740	
1741	void CopyNode::CollectFragmentLayouts(const PrimExpr &expr,
1742	                                      const Map<Var, PrimExpr> &let_var_to_expr,
1743	                                      const LayoutMap &existing_layouts,
1744	                                      PrimExpr thread_extent,
1745	                                      Range thread_bounds,
1746	                                      Map<Buffer, Layout> &result_map) const {
1747	  PostOrderVisit(expr, [&](const ObjectRef &node) {
1748	    if (auto bl = node.as<BufferLoadNode>()) {
1749	      if (IsFragmentBuffer(bl->buffer) && !existing_layouts.count(bl->buffer) &&
1750	          !result_map.count(bl->buffer)) {
1751	        auto f = Fragment::FullyReplicated(bl->buffer->shape, thread_extent);
1752	        result_map.Set(bl->buffer, f->BindThreadRange(thread_bounds));
1753	      }
1754	    } else if (auto var_node = node.as<VarNode>()) {
1755	      auto var = tvm::ffi::GetRef<Var>(var_node);
1756	      if (let_var_to_expr.count(var)) {
1757	        CollectFragmentLayouts(let_var_to_expr[var], let_var_to_expr,
1758	                               existing_layouts, thread_extent, thread_bounds,
1759	                               result_map);
1760	      }
1761	    }
1762	  });
1763	}
1764	
1765	// Register the Copy operation with TVM's TIR system
1766	// This makes the copy operation available for use in TVM programs
1767	// - Takes 5 inputs: src_buffer, dst_buffer, coalesced_width, disable_tma,
1768	// eviction_policy
1769	// - Marked as opaque since it has side effects (memory writes)
1770	TIR_REGISTER_TL_TILE_OP(Copy, copy)
1771	    .set_num_inputs(5)
1772	    .set_attr<TCallEffectKind>("TCallEffectKind",
1773	                               Integer(CallEffectKind::kOpaque));
1774	
1775	// Layout inference hook - returns empty map (no layout suggestions).
1776	LayoutMap Conv2DIm2ColOpNode::InferLayout(const LayoutInferArgs &T,
1777	                                          InferLevel level) const {
1778	  return {};
1779	}
1780	
1781	// Register the Conv2DIm2Col operation with TVM's TIR system
1782	// This operation performs im2col transformation for 2D convolutions using TMA
1783	// - Takes 9 inputs: src_buffer, dst_buffer, nhw_step, c_step, kernel, stride,
1784	// dilation, padding, eviction_policy
1785	// - Marked as opaque since it has side effects (memory writes)
1786	TIR_REGISTER_TL_TILE_OP(Conv2DIm2ColOp, c2d_im2col)
1787	    .set_num_inputs(9)
1788	    .set_attr<TCallEffectKind>("TCallEffectKind",
1789	                               Integer(CallEffectKind::kOpaque));
1790	
1791	TVM_FFI_STATIC_INIT_BLOCK() {
1792	  CopyNode::RegisterReflection();
1793	  Conv2DIm2ColOpNode::RegisterReflection();
1794	}
1795	} // namespace tl
1796	} // namespace tvm
